import {MEALS,mealFor} from './cooking-data.js';
import {ITEMS,CHAPTERS} from './data.js';
import {recipeVisited,recipeLearned,cookingQuote} from './cooking.js';

const item=(id,size=40)=>`<canvas class="item-sprite" data-item="${id}" width="32" height="32" style="width:${size}px;height:${size}px" aria-label="${ITEMS[id].name}"></canvas>`;
export function cookingMarkup(game,count=1){
 const packed=mealFor(game.packedMeal),known=MEALS.filter(r=>recipeLearned(game,r.id)),here=MEALS[game.region];
 return `<div class="kitchen-intro"><div class="kitchen-still">${item('snowbroth',94)}<span>食物的温度，也是归途</span></div><div><small>群岛风味手帖 · ${known.length} / 8 道食谱</small><h3>在路上，<br>好好吃一顿。</h3><p>向每座岛的料理人学一道手艺。食材可以在杂货铺补充，学会的料理随时都能制作。</p></div></div><div class="meal-packed ${packed?'is-packed':''}">${packed?item(packed.id,44):'<span class="empty-meal">▱</span>'}<div><small>下一场对战 · 待用餐盒</small><strong>${packed?packed.name:'还没有装盒'}</strong><p>${packed?packed.desc:'选择一道做好了的料理，陪队伍一起出发。'}</p></div>${packed?'<button class="secondary" id="unpack-meal">收回</button>':''}</div><p class="meal-rules">装盒不扣数量；开战时消耗 1 份，全队分享。一次只带一种效果，换人不重复触发。读档会保留已经使用的餐盒。</p><div class="kitchen-toolbar"><div role="group" aria-label="料理份数"><span>制作份数</span>${[1,3,5].map(n=>`<button data-cook-count="${n}" aria-pressed="${n===count}" class="${n===count?'active':''}">${n}</button>`).join('')}</div><button class="secondary" id="kitchen-shop">购买食材 →</button></div>${!recipeLearned(game,here.id)?`<div class="kitchen-lesson"><span>${item(here.id,44)}</span><div><strong>${here.chef} · ${CHAPTERS[game.region].town}</strong><p>${game.place==='town'?'这座岛有人正等着与你一起开火。首次学会后，赠送 1 份试吃餐盒。':'回到城镇，可以请教这座岛的料理人。'}</p></div>${game.place==='town'?`<button class="secondary" data-lesson="${here.id}">一起做饭</button>`:''}</div>`:''}<div class="supply-grid kitchen-grid">${MEALS.filter(r=>recipeVisited(game,r)||recipeLearned(game,r.id)).map(r=>{
 const learned=recipeLearned(game,r.id),q=cookingQuote(game,r.id,count),canLearn=game.region===r.region&&game.place==='town';
 return `<article class="supply-card recipe-card ${packed?.id===r.id?'selected':''}" style="--dish-color:${r.color}"><div class="dish-header"><div class="dish-portrait">${item(r.id,72)}</div><div><small>${CHAPTERS[r.region].island} · ${r.tag}</small><h3>${r.name}</h3><span>${learned?'食谱已记下':r.chef+'的拿手料理'}</span></div></div><p class="dish-effect">${r.desc}</p>${learned?`<div class="recipe-materials"><small>食材 · 持有 / 本次需要</small>${q.materials.map(m=>`<span class="${m.owned<m.need?'missing':''}"><i class="ingredient-name">${item(m.id,24)} ${ITEMS[m.id].name}</i><b>${m.owned} / ${m.need}</b></span>`).join('')}</div><div class="dish-actions"><small>餐盒 ${q.owned} 份</small><button data-pack-meal="${r.id}" ${q.owned&&packed?.id!==r.id?'':'disabled'}>${packed?.id===r.id?'已装盒':'装进餐盒'}</button><button class="secondary" data-cook="${r.id}" ${q.ok?'':'disabled'} aria-label="制作 ${r.name} ${count} 份">${q.ok?'制作 '+count+' 份':q.reason}</button></div>`:`<p class="recipe-lock">到 ${CHAPTERS[r.region].town} 请教 ${r.chef}，学会后才能制作。</p>`}<button class="text-button recipe-story" data-lesson="${r.id}" ${learned||canLearn?'':'disabled'}>${learned?'重读 · '+r.title:'听听 · '+r.title} →</button></article>`;
 }).join('')}</div><p class="section-note kitchen-next">每一座新岛屿，都有下一道尚未尝过的风味。</p><button class="text-button" id="kitchen-bag">返回旅行背包 →</button>`;
}
export function cookingLessonMarkup(game,id){
 const r=mealFor(id),learned=recipeLearned(game,id),choice=game.cookingLessons?.[id];
 return `<div class="recipe-reader" style="--dish-color:${r.color}"><div class="recipe-reader-head">${item(r.id,80)}<div><small>${CHAPTERS[r.region].town} · ${r.chef}</small><h3>${r.title}</h3></div></div><div class="recipe-prose">${r.story.map(p=>`<p>${p}</p>`).join('')}</div>${learned?`<div class="recipe-reply"><small>你当时说 · ${r.choices[choice].text}</small><p>${r.choices[choice].reply}</p></div><p class="section-note">食谱已收录，试吃餐盒已经领过。</p>`:`<div class="recipe-choices">${r.choices.map((c,i)=>`<button data-recipe-choice="${i}">${c.text}<span>→</span></button>`).join('')}</div><p class="section-note">学会「${r.name}」，获得 1 份试吃餐盒。</p>`}<button class="text-button" id="recipe-reader-back">回到露营厨房 →</button></div>`;
}
